// V457: local date/amount rows; canonical textarea also preserves previous drafts.
function syncFeeForm457(){
 const model=$('s336FeeInstallments'),host=$('s336FeeRows457'),kind=$('s336FeeKind');if(!model||!host||!kind)return;
 $('s336InstallmentBox').hidden=kind.value!=='installment';$('s336FeeAmount').parentElement.hidden=kind.value!=='monthly';
 const emit=()=>model.dispatchEvent(new Event('input',{bubbles:true}));
 const serialize=()=>{model.value=[...host.querySelectorAll('[data-fee-row457]')].map(row=>row.querySelector('[data-date457]').value+','+row.querySelector('[data-amount457]').value).join('\n')};
 const add=(date='',amount='')=>{if(host.children.length>=24)return status('अधिकतम 24 किस्तें रखें।',true);const row=document.createElement('div');row.className='s336FeeRow457';row.setAttribute('data-fee-row457','');row.innerHTML='<label>देय तारीख / Due date<input type="date" data-date457 value="'+E(date)+'"></label><label>राशि ₹ / Amount<input type="number" min="0" step="0.01" data-amount457 value="'+E(amount)+'"></label><button type="button" aria-label="किस्त हटाएँ / Remove installment">हटाएँ</button>';row.addEventListener('input',serialize);row.querySelector('button').onclick=()=>{row.remove();serialize();emit()};host.append(row)};
 host.replaceChildren();const lines=model.value.split('\n').filter(x=>x.trim());
 const invalidLegacy=lines.length>24||lines.some(line=>{const parts=line.split(',').map(x=>x.trim());return parts.length!==2||(parts[0]&&!validDate(parts[0]))||(parts[1]&&(!Number.isFinite(+parts[1])||+parts[1]<0))});
 if(invalidLegacy){model.hidden=false;model.setAttribute('aria-hidden','false');model.rows=6;const addButton=$('s336FeeAdd457');addButton.textContent='टेक्स्ट सुधारकर तारीख/राशि पंक्तियों में दिखाएँ';addButton.onclick=()=>{syncFeeForm457();emit()};if($('s336FeeSave'))$('s336FeeSave').disabled=true;status('पुराने draft की किस्तें नीचे पूरी रखी हैं। तारीख, राशि और अधिकतम 24 पंक्तियाँ जाँचें।',true);return}
 model.hidden=true;model.setAttribute('aria-hidden','true');$('s336FeeAdd457').textContent='＋ किस्त जोड़ें / Add installment';
 for(const line of lines){const parts=line.split(',');add(parts[0]?.trim()||'',parts[1]?.trim()||'')}
 if(!host.children.length&&kind.value==='installment')add($('s336FeeStart').value,'');
 $('s336FeeAdd457').onclick=()=>{add($('s336FeeStart').value,'');serialize();emit()};
 const save=$('s336FeeSave');if(save)save.disabled=true;
}

function parseInstallments(text){const rows=String(text).split('\n').filter(x=>x.trim()).map(x=>{const p=x.split(',').map(x=>x.trim());if(p.length!==2||!validDate(p[0])||p[1]===''||!Number.isFinite(+p[1])||+p[1]<0)throw Error('किस्त: तारीख, राशि लिखें।');return {date:p[0],amount:+p[1]}});if(!rows.length||rows.length>24||new Set(rows.map(x=>x.date)).size!==rows.length)throw Error('1–24 अलग किस्त तारीखें रखें।');return rows}
function validDate(x){return /^\d{4}-\d{2}-\d{2}$/.test(x)&&!Number.isNaN(Date.parse(x+'T00:00:00Z'))&&new Date(x+'T00:00:00Z').toISOString().slice(0,10)===x}
function planDates(d){if(!validDate(d.start_date)||!validDate(d.end_date)||d.start_date>d.end_date||!/^(\d{4})-\d{2}$/.test(d.academic_session))throw Error('सत्र और तारीख सही भरें।');const y=+d.academic_session.slice(0,4);if(d.start_date<`${y}-04-01`||d.end_date>`${y+1}-03-31`)throw Error('तारीख उसी April–March सत्र में रखें।');if(d.kind==='installment'){if(d.installments.some(x=>x.date<d.start_date||x.date>d.end_date))throw Error('किस्त तारीखें शुरू और अंत के बीच रखें।');return d.installments.slice().sort((a,b)=>a.date.localeCompare(b.date))}const date=new Date(d.start_date+'T00:00:00Z'),day=date.getUTCDate(),out=[];for(let i=0;i<12;i++){const first=new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth()+i,1));const last=new Date(Date.UTC(first.getUTCFullYear(),first.getUTCMonth()+1,0)).getUTCDate(),dt=new Date(Date.UTC(first.getUTCFullYear(),first.getUTCMonth(),Math.min(day,last))).toISOString().slice(0,10);if(dt>d.end_date)break;out.push({date:dt,amount:d.amount})}return out}
function renderFeeResult(r){const target=$('s336FeePreviewBox');if(target)target.innerHTML=`<div class="s336Good">✓ ${E(r.applied)} विद्यार्थियों पर योजना सेव • ${E(r.preserved)} व्यक्तिगत settings सुरक्षित • ${E(r.free)} फीस-मुक्त।</div>`;loadPlans().catch(e=>status(e.message,true));}
async function loadPlans(){if(!$('s336FeePlans'))return;try{const [plans,entries]=await Promise.all([rows('ldm_v336_fee_plans',q=>q.order('created_at',{ascending:false})),rows('ldm_v336_fee_entries',q=>q.eq('academic_session',session()).order('due_date'))]);if(!$('s336FeePlans'))return;$('s336FeePlans').innerHTML=table(plans,[['name','योजना'],['class_name','क्लास'],['kind','प्रकार'],['start_date','शुरू'],[p=>String(entries.filter(e=>e.plan_id===p.id&&e.status==='pending').length),'भविष्य/बाकी entries'],[p=>`<button data-plan-view="${E(p.id)}">तारीखें / स्थिति</button>${p.is_active!==false?`<button data-plan-pause="${E(p.id)}">आगे की फीस रोकें</button>`:'<small>योजना रोकी गई</small>'}`,'देखें']]);document.querySelectorAll('[data-plan-pause]').forEach(b=>b.onclick=()=>{if(confirm('इस योजना की अभी न बनी भविष्य की फीस रोकें? बनी bills और payments सुरक्षित रहेंगे।'))write('ldm_v336_fee_plan_pause',{p_request:crypto.randomUUID(),p_id:b.dataset.planPause},r=>{status('✓ आगे की '+r.cancelled_future+' entries रोकी गईं।');return loadPlans()})});document.querySelectorAll('[data-plan-view]').forEach(b=>b.onclick=()=>{$('s336FeePreviewBox').innerHTML=table(entries.filter(e=>e.plan_id===b.dataset.planView),[['admission_no','विद्यार्थी'],['due_date','तारीख'],[e=>cash(e.amount),'राशि'],['status','स्थिति']]);});}catch(e){if($('s336FeePlans'))$('s336FeePlans').textContent=e.message}}
async function bank(){if(!bankPromise)bankPromise=fetch(new URL('teacher-development-v336.json',document.baseURI)).then(r=>{if(!r.ok)throw Error('शिक्षक सामग्री file नहीं मिली');return r.json()}).catch(e=>{bankPromise=null;throw e});return bankPromise}
function dailySet(data,date){if(!validDate(date)||date<data.start||date>data.end)throw Error(`तारीख ${data.start} से ${data.end} के बीच चुनें।`);const day=Math.floor((Date.parse(date+'T00:00:00Z')-Date.parse(data.start+'T00:00:00Z'))/86400000);const base=(day*5+Math.floor(day/24)*17)%data.words.length;return {day:day+1,date,words:Array.from({length:5},(_,i)=>data.words[(base+i)%data.words.length]),gk:Object.values(data.knowledge).map((xs,i)=>xs[(day*7+i*3)%xs.length]),quotes:[data.quotes[(day*7)%data.quotes.length],data.quotes[(day*7+9)%data.quotes.length]],guide:data.guidelines[day%data.guidelines.length]}}
async function teacherDay(mine){shell('दैनिक शिक्षक विकास','5 शब्द • 5 GK • 2 प्रेरक विचार • जिम्मेदार और सम्मानपूर्ण शिक्षक व्यवहार');const data=await bank();if(mine!==epoch)return;let date=readDate;if(date<data.start)date=data.start;if(date>data.end)date=data.end;$('s336Body').innerHTML=`<div class="s336Tools"><button id="s336DayPrev">← पिछला दिन</button>${field('s336ReadDate','दिन चुनें','date',date)}<button id="s336DayToday">आज</button><button id="s336DayNext">अगला दिन →</button></div><div id="s336Daily"></div><p class="s336Muted">${E(data.notice)}</p><details><summary>संदर्भ और सामग्री का आधार</summary>${data.sources.map(s=>`<p><a href="${E(s.url)}" target="_blank" rel="noopener">${E(s.title)}</a></p>`).join('')}</details>`;
 const paint=()=>{try{const x=dailySet(data,$('s336ReadDate').value);readDate=x.date;$('s336Daily').innerHTML=`<h3>दिन ${x.day} • ${E(x.date)}</h3><div class="s336Bank"><section class="s336Panel"><h3>5 English शब्द</h3>${x.words.map(w=>`<div class="s336Word"><b>${E(w.word)}</b> • ${E(w.pronunciation)}<p>${E(w.meaning)}</p><small>${E(w.example)}</small></div>`).join('')}</section><section class="s336Panel"><h3>5 सामान्य ज्ञान</h3>${x.gk.map((q,i)=>`<div class="s336Word"><b>${i+1}. ${E(q.question)}</b><p>${E(q.answer)}</p></div>`).join('')}</section></div>${x.quotes.map(q=>`<div class="s336Quote"><b>${E(q.hi)}</b><p>${E(q.en)}</p><small>${E(q.attribution)}</small></div>`).join('')}<section class="s336Panel"><h3>आज का मार्गदर्शन</h3><p>${E(x.guide)}</p><button id="s336ReadDone" class="primary">${E(x.date)} का अध्ययन पढ़ लिया</button><p class="s336Muted">यह स्वघोषित अध्ययन रिकॉर्ड है; पढ़ने या समझने का स्वतः प्रमाण नहीं।</p></section>`;$('s336ReadDone').onclick=()=>recordSave({kind:'teacher_read',title:'शिक्षक अध्ययन '+x.date,status:'done',due_date:x.date,payload:{date:x.date,day:x.day}},null,()=>{$('s336ReadDone').disabled=true;status('✓ अध्ययन रिकॉर्ड सेव हुआ।')});$('s336DayPrev').disabled=x.date===data.start;$('s336DayNext').disabled=x.date===data.end;}catch(e){status(e.message,true)}};
 $('s336ReadDate').min=data.start;$('s336ReadDate').max=data.end;$('s336ReadDate').onchange=paint;const shift=n=>{$('s336ReadDate').value=new Date(Date.parse($('s336ReadDate').value+'T00:00:00Z')+n*86400000).toISOString().slice(0,10);paint()};$('s336DayPrev').onclick=()=>shift(-1);$('s336DayNext').onclick=()=>shift(1);$('s336DayToday').onclick=()=>{$('s336ReadDate').value=today();paint()};paint();}
function legacyWork(rows,assignments=[]){return rows.filter(t=>t.is_active!==false&&!['cancelled','archived'].includes(String(t.status).toLowerCase())).map(t=>{const mine=assignments.find(a=>a.task_id===t.id&&a.teacher_auth_user_id===actor()?.id);const raw=teacher()&&mine?mine.status:t.status;return {...t,id:'legacy:'+t.id,_legacy:true,status:['completed','verified','approved','done'].includes(String(raw).toLowerCase())?'done':'open',payload:{note:t.details||''}}})}
async function getLegacyWork(){const [ts,as]=await Promise.all([source('ldm_work_tasks',q=>q.order('created_at',{ascending:false})),source('ldm_work_task_assignees',q=>teacher()?q.eq('teacher_auth_user_id',actor()?.id).order('assigned_at'):q.order('assigned_at'))]);const allowed=teacher()?ts.rows.filter(t=>as.rows.some(a=>a.task_id===t.id&&a.is_active!==false)):ts.rows;return {ok:ts.ok&&as.ok,error:[ts.error,as.error].filter(Boolean).join(' • '),rows:legacyWork(allowed,as.rows)}}
async function tasks(mine){shell(teacher()?'मेरी जिम्मेदारियाँ':'आज का जरूरी काम','एक जिम्मेदारी • जिम्मेदार व्यक्ति • तारीख • प्रगति');const [native,profiles,legacy]=await Promise.all([rows('ldm_v336_records',q=>q.eq('academic_session',session()).in('kind',['task','support','substitution']).order('created_at',{ascending:false})),admin()?getProfiles():Promise.resolve([]),getLegacyWork()]);if(mine!==epoch)return;const tasks=[...native,...legacy.rows];staffRows=profiles;let filter='open';$('s336Body').innerHTML=`${warnSources({पुरानी_जिम्मेदारियाँ:legacy})}${links([[teacher()?'मूल Assigned Work':'मूल Assign Work',teacher()?'assigned_work':'work_delegation']])}${admin()?`<section class="s336Panel"><h3>नई जिम्मेदारी</h3><div class="s336Tools">${field('s336TaskTitle','क्या काम करना है')}${teacherSelect('s336TaskTeacher')}${field('s336TaskDate','कब तक','date',today())}<label class="s336Wide">विवरण<textarea id="s336TaskNote" rows="3"></textarea></label><button id="s336TaskSave" class="primary">जिम्मेदारी सेव करें</button></div></section>`:''}<div class="s336Tools"><label>स्थिति<select id="s336TaskFilter"><option value="open">बाकी</option><option value="done">पूरे</option><option value="all">सभी</option></select></label><input id="s336TaskSearch" placeholder="काम खोजें"></div><div id="s336TaskList" class="s336List"></div>`;
 const paint=()=>{const q=$('s336TaskSearch').value.toLowerCase(),filter=$('s336TaskFilter').value;const shown=tasks.filter(t=>(filter==='all'||t.status===filter)&&[t.title,t.payload?.note,t.payload?.completion_note].some(v=>String(v||'').toLowerCase().includes(q)));$('s336TaskList').innerHTML=shown.map(t=>`<article class="s336Item"><h3>${E(t.title)}</h3><p>${E(t.payload?.note||t.payload?.summary||'')}</p><p>तारीख: ${E(t.due_date||'—')} • स्थिति: ${E(t.status)} • जिम्मेदार: ${E(profiles.find(p=>p.id===t.assigned_to)?.full_name||t.assigned_to||'Admin')}</p>${t.payload?.completion_note?`<p>प्रगति: ${E(t.payload.completion_note)}</p>`:''}${t._legacy?`<p>मूल Assign Work से जुड़ा रिकॉर्ड</p><button data-old-route="${teacher()?'assigned_work':'work_delegation'}">उसी मूल रिकॉर्ड में प्रगति दर्ज करें</button>`:`<div class="s336Tools">${field('progress_'+t.id,'प्रगति / पूरा करने की टिप्पणी','text',t.payload?.completion_note||'')}<button data-work-update="${E(t.id)}">${t.status==='done'?'फिर बाकी रखें':'पूरा दर्ज करें'}</button></div>`}</article>`).join('')||'<p>इस फ़िल्टर में कोई काम नहीं।</p>';document.querySelectorAll('[data-work-update]').forEach(b=>b.onclick=()=>{const t=tasks.find(t=>t.id===b.dataset.workUpdate);recordSave({...t,status:t.status==='done'?'open':'done',payload:{...t.payload,completion_note:$('progress_'+t.id).value}},t,()=>open('tasks'))});};$('s336TaskFilter').onchange=paint;$('s336TaskSearch').oninput=paint;if($('s336TaskSave'))$('s336TaskSave').onclick=()=>{const title=$('s336TaskTitle').value.trim();if(!title)return status('काम लिखें।',true);recordSave({kind:'task',title,due_date:$('s336TaskDate').value,assigned_to:$('s336TaskTeacher').value||null,payload:{note:$('s336TaskNote').value}},null,()=>open('tasks'))};paint();}
async function collectOperations(){const day=today(),weekday=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Kolkata',weekday:'long'}).format(new Date());const names=['students','attendance','timetable','staff_attendance','work','diary','marks','payments','holidays','legacyWork','legacyAssignments','teacherRequests','studentRequests'];const results=await Promise.all([source('students',q=>q.order('id')),source('attendance',q=>q.eq('date',day).order('id')),source('timetable',q=>q.eq('day_name',weekday).order('period_no')),source('staff_attendance',q=>q.eq('date',day).order('id')),source('ldm_v336_records',q=>q.eq('academic_session',session()).in('kind',['task','support','substitution']).order('created_at')),source('teaching_diary',q=>q.eq('teaching_date',day).order('id')),source('student_marks',q=>q.eq('academic_session',session()).order('id')),source('fee_payments',q=>q.eq('payment_date',day).order('id')),source('school_holidays',q=>q.eq('holiday_date',day).order('id')),source('ldm_work_tasks',q=>q.order('created_at')),source('ldm_work_task_assignees',q=>q.order('assigned_at')),source('v90_teacher_requests',q=>q.order('created_at')),source('student_roster_requests',q=>q.order('created_at'))]);const data=Object.fromEntries(names.map((n,i)=>[n,results[i]]));const students=data.students.rows.filter(active).filter(s=>!s.academic_session||s.academic_session===session()),att=new Set(data.attendance.rows.map(a=>a.admission_no)),unmarked=students.filter(s=>!att.has(s.admission_no)),absentNames=new Set(data.staff_attendance.rows.filter(a=>['absent','leave'].includes(String(a.status).toLowerCase())).map(a=>String(a.staff_name||a.teacher_name||'').toLowerCase().trim())),periods=data.timetable.rows.filter(t=>!t.teacher_name||absentNames.has(String(t.teacher_name).toLowerCase().trim())),work=[...data.work.rows,...legacyWork(data.legacyWork.rows,data.legacyAssignments.rows)].filter(t=>t.status==='open'),blankMarks=data.marks.rows.filter(m=>m.marks_obtained===null||m.obtained_marks===null||m.marks===null);return {day,weekday,data,students,unmarked,periods,work,blankMarks,holiday:data.holidays.ok&&data.holidays.rows.length>0,collection:data.payments.rows.reduce((n,p)=>n+Number(p.amount||0),0)}}
async function operations(mine){shell('मेरी जगह स्कूल देखो','आज की वास्तविक प्रविष्टियाँ • खाली/अधूरे काम • सीधे अगले कदम');$('s336Body').innerHTML='<p>आज का मिलान हो रहा है…</p>';const d=await collectOperations();if(mine!==epoch)return;const counts=[['उपस्थिति बाकी',d.data.attendance.ok&&d.data.students.ok&&!d.holiday?d.unmarked.length:'जाँचें'],['खाली / अनुपस्थित शिक्षक के पीरियड',d.data.timetable.ok&&d.data.staff_attendance.ok?d.periods.length:'जाँचें'],['बाकी जिम्मेदारियाँ',d.data.work.ok&&d.data.legacyWork.ok&&d.data.legacyAssignments.ok?d.work.length:'आंशिक / जाँचें'],['आज जमा',d.data.payments.ok?cash(d.collection):'जाँचें']];$('s336Body').innerHTML=`${warnSources(d.data)}<p>${E(d.day)} • ${E(d.weekday)}${d.holiday?' • अवकाश रिकॉर्ड मिला; उपस्थिति की कमी को अनुपस्थिति नहीं माना गया।':''}</p><div class="s336Stats">${counts.map(([k,v])=>`<div><small>${E(k)}</small><b>${E(v)}</b></div>`).join('')}</div><section class="s336Panel"><h3>उपस्थिति अभी दर्ज नहीं</h3><p>Unmarked का मतलब Absent नहीं है।</p>${table(d.unmarked.slice(0,30),[['student_name','नाम'],['class_name','क्लास'],['admission_no','प्रवेश संख्या']])}${links([['उपस्थिति दर्ज करें','attendance']])}</section><section class="s336Panel"><h3>पीरियड व्यवस्था चाहिए</h3>${table(d.periods,[['class_name','क्लास'],['period_no','पीरियड'],['subject','विषय'],['teacher_name','शिक्षक']])}<button data-route="substitution">वैकल्पिक शिक्षक तय करें</button></section><section class="s336Panel"><h3>बाकी काम</h3>${table(d.work,[['title','काम'],['due_date','तारीख'],['status','स्थिति']])}<button data-route="tasks">जिम्मेदारियाँ खोलें</button></section><section class="s336Panel"><h3>लंबित आवेदन / अनुरोध</h3>${table([...d.data.teacherRequests.rows,...d.data.studentRequests.rows].filter(r=>String(r.status||'pending').toLowerCase()==='pending'),[[r=>E(r.teacher_name||r.student_name||r.requested_by_name||'अनुरोध'),'नाम'],[r=>E(r.request_type||r.leave_type||''),'प्रकार'],[r=>E(r.reason||r.details||''),'विवरण']])}${links([['शिक्षक अनुरोध पर निर्णय','v90_teacher_requests'],['विद्यार्थी अनुरोध पर निर्णय','v90_student_requests']])}</section><section class="s336Panel"><h3>अंक / पढ़ाई</h3><p>मौजूदा अंक पंक्तियों में खाली अंक: ${d.data.marks.ok?d.blankMarks.length:'स्रोत की जाँच बाकी'}। जिनकी अंक पंक्ति अभी बनी ही नहीं, उनकी जाँच मूल Central Exam के Pending फ़िल्टर से करें।</p><p>आज teaching diary की प्रविष्टियाँ: ${d.data.diary.ok?d.data.diary.rows.length:'स्रोत की जाँच बाकी'}</p>${links([['Central Exam / Pending','central_exam'],['Teaching Monitor','v90_teaching_monitor']])}</section>`;}
async function student(mine){shell('विद्यार्थी और अभिभावक सहायता','एक खोज • पूरा विद्यार्थी रिकॉर्ड • बातचीत का अगला कदम');$('s336Body').innerHTML=`<section class="s336Panel"><div class="s336Tools"><input id="s336StudentQ" placeholder="नाम / पिता / मोबाइल / प्रवेश संख्या"><button id="s336FindStudent" class="primary">खोजें</button><button id="s336MoreStudents" disabled>अगले 50</button></div><div id="s336StudentResults"></div></section><div id="s336StudentDetail"></div>`;let offset=0,query='';const search=async(more=false)=>{if(!more){offset=0;query=$('s336StudentQ').value.trim().replace(/[%,_().\\"']/g,' ')}if(query.length<2)return status('कम से कम 2 अक्षर / अंक लिखें।',true);try{const data=await request(db().from('students').select('*').or(['student_name','father_name','phone','admission_no'].map(k=>k+'.ilike.%'+query+'%').join(',')).order('id').range(offset,offset+49));if(mine!==epoch)return;const shown=data.filter(active);$('s336StudentResults').innerHTML=table(shown,[[s=>`<button data-student="${E(s.id)}">${E(s.student_name)}</button>`,'नाम'],['father_name','पिता'],['class_name','क्लास'],['admission_no','प्रवेश संख्या']]);$('s336MoreStudents').disabled=data.length<50;offset+=50;document.querySelectorAll('[data-student]').forEach(b=>b.onclick=()=>loadStudent(shown.find(s=>s.id===b.dataset.student),mine));}catch(e){status(e.message,true)}};$('s336FindStudent').onclick=()=>search();$('s336MoreStudents').onclick=()=>search(true);$('s336StudentQ').onkeydown=e=>{if(e.key==='Enter')search()};}
async function loadStudent(s,mine){const studentToken=++studentEpoch;currentRecord=s;status('विद्यार्थी का रिकॉर्ड मिल रहा है…');const names=['attendance','marks','payments','documents','contacts'];const r=await Promise.all([source('attendance',q=>q.eq('admission_no',s.admission_no).order('date',{ascending:false})),source('student_marks',q=>q.eq('admission_no',s.admission_no).order('exam_name')),source('fee_payments',q=>q.eq('admission_no',s.admission_no).order('payment_date',{ascending:false})),source('ldm_v336_session_archive',q=>q.eq('student_id',s.id).order('academic_session')),source('ldm_v336_records',q=>q.eq('student_id',s.id).eq('kind','contact').order('created_at',{ascending:false}))]);let due;try{const rows=await rpc('ldm_fee_due_snapshot_v2',{p_session:session(),p_admission_nos:[s.admission_no],p_until_month:today().slice(0,7)});if(rows.length!==1)throw Error('अधूरा बकाया उत्तर');due=rows[0].current_due}catch(e){due=null;status('फीस: '+e.message,true)}if(mine!==epoch||studentToken!==studentEpoch)return;const data=Object.fromEntries(names.map((n,i)=>[n,r[i]]));$('s336StudentDetail').innerHTML=`<section class="s336Panel"><h2>${E(s.student_name)}</h2><p>${E(s.class_name)} • ${E(s.admission_no)} • पिता: ${E(s.father_name)} • मोबाइल: ${E(s.phone)}</p><p>केंद्रीय बकाया: <b>${due===null?'सत्यापन बाकी':cash(due)}</b></p>${warnSources(data)}<div class="s336Tools"><button id="s336OriginalStudent">मूल पूरा विद्यार्थी रिकॉर्ड / दस्तावेज</button><button id="s336StudentFee">मूल Fee Account</button><button data-route="support">सहायता योजना</button></div><details open><summary>हाल की उपस्थिति</summary>${table(data.attendance.rows.slice(0,30),[['date','तारीख'],['status','स्थिति']])}</details><details><summary>अंक</summary>${table(data.marks.rows,[['exam_name','परीक्षा'],['subject_name','विषय'],[m=>E(m.marks_obtained??m.obtained_marks??m.marks??'Pending'),'अंक']])}</details><details><summary>भुगतान</summary>${table(data.payments.rows,[['payment_date','तारीख'],['receipt_no','रसीद'],[r=>cash(r.amount),'राशि']])}</details><details><summary>पुराने सत्र का विद्यार्थी रिकॉर्ड</summary>${table(data.documents.rows,[['academic_session','सत्र'],[a=>E(a.snapshot?.student?.class_name),'पुरानी क्लास']])}</details><h3>अभिभावक बातचीत दर्ज करें</h3><div class="s336Tools">${field('s336ContactWho','किससे बात हुई','text',s.father_name||'')}${field('s336ContactNext','अगली बातचीत','date',today())}<label class="s336Wide">बात और सहमति से तय अगला कदम<textarea id="s336ContactNote" rows="4"></textarea></label><button id="s336ContactSave" class="primary">बातचीत सेव करें</button></div><h3>पिछली बातचीत</h3>${data.contacts.rows.map(x=>`<article class="s336Item"><b>${E(x.payload?.who)}</b><p>${E(x.payload?.note)}</p><small>अगला कदम: ${E(x.due_date||'—')} • ${E(x.created_at)}</small></article>`).join('')||'<p>बातचीत रिकॉर्ड नहीं है।</p>'}</section>`;$('s336ContactSave').onclick=()=>{const note=$('s336ContactNote').value.trim();if(!note)return status('बातचीत लिखें।',true);recordSave({kind:'contact',student_id:s.id,title:'अभिभावक संपर्क: '+s.student_name,due_date:$('s336ContactNext').value||null,payload:{who:$('s336ContactWho').value,note}},null,()=>loadStudent(s,mine))};$('s336StudentFee').onclick=()=>W.v111OpenFeePlanner?W.v111OpenFeePlanner(s.id):W.openStudentFeeAccount(s.id);$('s336OriginalStudent').onclick=async()=>{await W.render('v150_student_master');if(typeof W.dashboardStudentFull==='function')return W.dashboardStudentFull(s.id);if($('v150SMQ')){$('v150SMQ').value=s.admission_no;W.v150RenderStudents?.()}};status('रिकॉर्ड लोड हुआ।');bindDraft();}
function scoreValue(m){const a=m.marks_obtained??m.obtained_marks??m.marks,max=m.max_marks??m.maximum_marks;if(a===null||a===undefined||a===''||max===null||max===undefined||+max<=0||!Number.isFinite(+a))return null;return 100*(+a)/(+max)}
function supportSignals(students,attendance,marks){return students.map(s=>{const absent=attendance.filter(a=>a.admission_no===s.admission_no&&String(a.status).toLowerCase()==='absent').length;const groups=new Map(),examDates=new Map();for(const m of marks.filter(m=>m.admission_no===s.admission_no)){const value=scoreValue(m);if(value===null)continue;const k=m.exam_name||'अज्ञात परीक्षा';if(!groups.has(k))groups.set(k,[]);groups.get(k).push(value);const md=String(m.exam_date||m.assessment_date||m.date||'').slice(0,10);if(validDate(md)&&(!examDates.get(k)||md>examDates.get(k)))examDates.set(k,md)}const means=[...groups].map(([exam,xs])=>({exam,date:examDates.get(exam)||null,percent:xs.reduce((a,b)=>a+b,0)/xs.length}));const dated=means.filter(m=>m.date).sort((a,b)=>a.date.localeCompare(b.date)),fall=dated.length>1?dated.at(-2).percent-dated.at(-1).percent:0;return {student:s,absent,means,fall,low:means.some(m=>m.percent<40)};}).filter(x=>x.absent>=3||x.low||x.fall>=10)}
async function support(mine){shell('विद्यार्थी सहायता और समीक्षा','संकेतों की शिक्षक द्वारा जाँच • छोटा लक्ष्य • जिम्मेदारी • अगली समीक्षा');const since=new Date(Date.parse(today()+'T00:00:00Z')-30*86400000).toISOString().slice(0,10);const [ss,att,marks,work,staff]=await Promise.all([getStudents(),source('attendance',q=>q.gte('date',since).order('date')),source('student_marks',q=>q.eq('academic_session',session()).order('id')),source('ldm_v336_records',q=>q.eq('kind','support').eq('academic_session',session()).order('created_at',{ascending:false})),getProfiles()]);if(mine!==epoch)return;studentRows=ss;staffRows=staff;const signals=supportSignals(ss,att.rows,marks.rows);$('s336Body').innerHTML=`${warnSources({attendance:att,marks,plans:work})}<section class="s336Panel"><h3>समीक्षा योग्य संकेत</h3><p>पिछले 30 दिन में कम से कम 3 दर्ज अनुपस्थितियाँ या उपलब्ध मान्य प्रतिशत में 40% से कम अंक, या उपलब्ध तारीख वाली अंतिम दो परीक्षाओं में कम से कम 10 प्रतिशत-अंक की गिरावट। परीक्षा तारीख उपलब्ध न हो तो गिरावट का अनुमान नहीं लगाया जाता। यह सहायता का संकेत है; बच्चे को दोषी या अयोग्य बताने का आधार नहीं। अलग परीक्षाओं की कठिनाई अलग हो सकती है।</p>${table(signals,[[x=>`<button data-help-student="${E(x.student.id)}">${E(x.student.student_name)}</button>`,'विद्यार्थी'],[x=>E(x.student.class_name),'क्लास'],[x=>String(x.absent),'दर्ज अनुपस्थिति'],[x=>x.means.map(m=>`${E(m.exam)}: ${m.percent.toFixed(1)}%`).join('<br>')+(x.fall>=10?`<br>गिरावट: ${x.fall.toFixed(1)} प्रतिशत-अंक`:''),'उपलब्ध प्रतिशत']])}</section><section class="s336Panel"><h3>सहायता योजना</h3><div class="s336Tools"><label>विद्यार्थी<select id="s336HelpStudent"><option value="">चुनें</option>${ss.map(s=>`<option value="${E(s.id)}">${E(s.student_name)} • ${E(s.class_name)} • ${E(s.admission_no)}</option>`).join('')}</select></label>${teacherSelect('s336HelpTeacher')}${field('s336HelpReview','अगली समीक्षा','date',today())}${field('s336HelpGoal','छोटा, जाँचा जा सकने वाला लक्ष्य')}<label class="s336Wide">सहायता / अभ्यास / अभिभावक सहयोग<textarea id="s336HelpNote" rows="4"></textarea></label><button id="s336HelpSave" class="primary">योजना सेव करें</button></div></section><section class="s336Panel"><h3>सहेजी योजनाएँ</h3>${table(work.rows,[['title','लक्ष्य'],['due_date','समीक्षा'],['status','प्रगति'],[r=>E(r.payload?.note),'सहायता']])}<button data-route="tasks">प्रगति और पूरा होने की टिप्पणी दर्ज करें</button></section>`;document.querySelectorAll('[data-help-student]').forEach(b=>b.onclick=()=>{$('s336HelpStudent').value=b.dataset.helpStudent;$('s336HelpGoal').focus()});$('s336HelpSave').onclick=()=>{const s=ss.find(x=>x.id===$('s336HelpStudent').value),goal=$('s336HelpGoal').value.trim();if(!s||!goal)return status('विद्यार्थी और लक्ष्य चुनें।',true);recordSave({kind:'support',student_id:s.id,assigned_to:$('s336HelpTeacher').value||null,title:s.student_name+' • '+goal,due_date:$('s336HelpReview').value,payload:{note:$('s336HelpNote').value,goal,admission_no:s.admission_no}},null,()=>open('support'))};}
function freeTeachers(all,tt,absent,period,date,existing=[],start='',end=''){const occupied=new Set(tt.filter(t=>String(t.period_no)===String(period)||start&&end&&t.start_time&&t.end_time&&String(t.start_time)<end&&start<String(t.end_time)).map(t=>String(t.teacher_name||'').trim().toLowerCase()));const blocked=new Set(absent.map(x=>String(x).trim().toLowerCase()));const assigned=new Set(existing.filter(r=>r.status!=='archived'&&r.due_date===date&&String(r.payload?.period_no)===String(period)).map(r=>r.assigned_to));return all.filter(t=>!occupied.has(String(t.full_name||t.name||'').trim().toLowerCase())&&!blocked.has(String(t.full_name||t.name||'').trim().toLowerCase())&&!assigned.has(t.id))}
async function substitution(mine){shell('वैकल्पिक पीरियड व्यवस्था','वास्तविक timetable में खाली समय देखें • Admin पुष्टि से ड्यूटी दें');const staff=await getProfiles();if(mine!==epoch)return;staffRows=staff;$('s336Body').innerHTML=`<section class="s336Panel"><div class="s336Tools">${field('s336SubDate','तारीख','date',today())}<label>अनुपस्थित शिक्षक<select id="s336SubAbsent"><option value="">चुनें</option>${staff.map(s=>`<option value="${E(s.full_name||s.name||'')}">${E(s.full_name||s.name||s.email)}</option>`).join('')}</select></label><button id="s336SubLoad" class="primary">खाली पीरियड / विकल्प देखें</button></div><div id="s336SubBody"></div></section>`;$('s336SubLoad').onclick=async()=>{try{const date=$('s336SubDate').value;if(!validDate(date))throw Error('तारीख चुनें');const absent=$('s336SubAbsent').value;if(!absent)throw Error('अनुपस्थित शिक्षक चुनें');const weekday=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Kolkata',weekday:'long'}).format(new Date(date+'T12:00:00+05:30'));const [tt,saved,attendance]=await Promise.all([rows('timetable',q=>q.eq('day_name',weekday).order('period_no')),rows('ldm_v336_records',q=>q.eq('kind','substitution').eq('due_date',date).order('id')),source('staff_attendance',q=>q.eq('date',date).order('id'))]);if(mine!==epoch)return;const absentAll=[absent,...attendance.rows.filter(x=>['absent','leave'].includes(String(x.status).toLowerCase())).map(x=>x.staff_name)],periods=tt.filter(t=>!t.teacher_name||String(t.teacher_name).toLowerCase()===absent.toLowerCase());$('s336SubBody').innerHTML=warnSources({attendance})+periods.map((t,i)=>{const options=freeTeachers(staff,tt,absentAll,t.period_no,date,saved,String(t.start_time||''),String(t.end_time||''));return `<article class="s336Item"><h3>क्लास ${E(t.class_name)} • पीरियड ${E(t.period_no)} • ${E(t.subject)}</h3><p>${E(t.start_time||'')}–${E(t.end_time||'')}</p><label>उपलब्ध शिक्षक<select id="sub_${i}"><option value="">${options.length?'चुनें':'उपलब्ध verified शिक्षक नहीं'}</option>${options.map(p=>`<option value="${E(p.id)}">${E(p.full_name||p.name||p.email)}</option>`).join('')}</select></label><button data-sub-save="${i}">ड्यूटी सेव करें</button></article>`}).join('')+`<h3>पहले से तय ड्यूटी</h3>${table(saved,[['title','ड्यूटी'],['due_date','दिन'],['status','स्थिति']])}`;document.querySelectorAll('[data-sub-save]').forEach(b=>b.onclick=()=>{const i=+b.dataset.subSave,t=periods[i],chosen=staff.find(p=>p.id===$('sub_'+i).value);if(!chosen)return status('उपलब्ध शिक्षक चुनें।',true);recordSave({kind:'substitution',title:`${t.class_name} • पीरियड ${t.period_no} • ${t.subject}`,assigned_to:chosen.id,due_date:date,payload:{teacher_name:chosen.full_name||chosen.name,absent_teacher:absent,class_name:t.class_name,period_no:t.period_no,subject:t.subject,day_name:weekday,start_time:t.start_time,end_time:t.end_time}},null,()=>{$('s336SubLoad').click()})});}catch(e){status(e.message,true)}};}
function findIssues(students,marks){const issues=[],adm=new Map(),roll=new Map();for(const s of students){const a=String(s.admission_no||'').trim().toLowerCase();if(!a)issues.push({type:'प्रवेश संख्या गायब',student:s.student_name,id:s.id});else {if(adm.has(a))issues.push({type:'डुप्लिकेट प्रवेश संख्या',student:s.student_name+' / '+adm.get(a),id:s.id});adm.set(a,s.student_name)}if(!/^\d{10}$/.test(String(s.phone||'').replace(/\D/g,'').slice(-10)))issues.push({type:'मोबाइल जाँचें',student:s.student_name,id:s.id});if(!s.class_name)issues.push({type:'क्लास गायब',student:s.student_name,id:s.id});const key=canon(s.class_name)+'|'+String(s.section||'')+'|'+String(s.roll_no||'');if(s.roll_no&&roll.has(key))issues.push({type:'क्लास/सेक्शन में समान रोल',student:s.student_name+' / '+roll.get(key),id:s.id});if(s.roll_no)roll.set(key,s.student_name)}for(const m of marks){const val=m.marks_obtained??m.obtained_marks??m.marks,max=m.max_marks??m.maximum_marks;if(val!==undefined&&val!==null&&val!==''&&(!Number.isFinite(+val)||+val<0||max!==undefined&&+max>0&&+val>+max))issues.push({type:'अमान्य अंक',student:m.admission_no+' • '+m.subject_name,id:m.id});}return issues}
async function checks(mine){shell('गलती जाँच केंद्र','रिकॉर्ड बदलने से पहले समीक्षा • स्वयं कोई डेटा नहीं मिटेगा');const [ss,marks]=await Promise.all([getStudents(),source('student_marks',q=>q.eq('academic_session',session()).order('id'))]);if(mine!==epoch)return;const issues=findIssues(ss,marks.rows);let feeError='',feeCount=0;try{for(let i=0;i<ss.length;i+=300){const r=await rpc('ldm_fee_due_snapshot_v2',{p_session:session(),p_admission_nos:ss.slice(i,i+300).map(s=>s.admission_no),p_until_month:today().slice(0,7)});feeCount+=r.length}}catch(e){feeError=e.message}$('s336Body').innerHTML=`${warnSources({marks})}<section class="s336Panel"><p>विद्यार्थी: ${ss.length} • मिले संकेत: ${issues.length} • केंद्रीय फीस का उत्तर: ${feeError?'अधूरा / त्रुटि':feeCount+' रिकॉर्ड'}</p>${feeError?`<p class="s336Error">${E(feeError)}</p>`:''}${table(issues,[['type','जाँच'],['student','संबंधित रिकॉर्ड']])}${links([['मूल विद्यार्थी संपादन','v150_student_master'],['Central Exam / अंक','central_exam'],['केंद्रीय बकाया','v200_due_fee_report']])}<p>ये चयनित जाँच हैं; पूरे ERP की त्रुटिरहित होने की गारंटी नहीं। स्रोत की त्रुटि होने पर जाँच अधूरी मानी जाएगी।</p><button id="s336DependencyCheck">ERP database functions की उपलब्धता जाँचें</button><div id="s336DependencyResults"></div></section>`;$('s336DependencyCheck').onclick=async()=>{try{const response=await fetch(new URL('UPDATE_V336/LEGACY_DATABASE_DEPENDENCIES.json',document.baseURI));if(!response.ok)throw Error('Dependency सूची file upload करें');const def=await response.json(),r=await rpc('ldm_v336_database_health',{p_functions:def.required_literal_functions||def.definitions_not_shipped});if(mine!==epoch)return;const missing=r.filter(x=>!x.present);$('s336DependencyResults').innerHTML=`<p>${r.length} function names में ${missing.length} उपलब्ध नहीं मिले। यह नाम और signatures की inventory है; policies और व्यवहार की अलग live जाँच चाहिए।</p>`+table(r,[['name','Function'],[x=>x.present?'उपलब्ध':'नहीं मिला','स्थिति'],[x=>E((x.signatures||[]).join(' • ')),'Signatures']]);}catch(e){status(e.message,true)}};}
