 const load=async()=>{try{const [xs,jobs]=await Promise.all([request(db().from('ldm_v336_backups').select('id,created_at,reason').order('created_at',{ascending:false}).limit(30)),request(db().from('ldm_v336_job_runs').select('id,run_at,result').order('id',{ascending:false}).limit(1))]);if(mine!==epoch)return;$('s336BackupScheduler').innerHTML=jobs.length?`<p class="s336Good">आखिरी scheduler run: ${E(jobs[0].run_at)}</p>`:'<p class="s336Error">स्वचालित job का सफल run अभी दर्ज नहीं। pg_cron या hosting cron configuration की जाँच करें। केवल snapshot button चलाना automatic backup नहीं है।</p>';$('s336BackupList').innerHTML=table(xs,[['created_at','समय'],['reason','कारण'],[r=>`<button data-backup-download="${E(r.id)}">JSON डाउनलोड</button><button data-backup-preview="${E(r.id)}">Restore Preview</button>`,'क्रिया']]);document.querySelectorAll('[data-backup-download]').forEach(b=>b.onclick=async()=>{try{const d=await request(db().from('ldm_v336_backups').select('payload').eq('id',b.dataset.backupDownload).single());download(d.payload,'LDM-backup-'+today()+'.json')}catch(e){status(e.message,true)}});document.querySelectorAll('[data-backup-preview]').forEach(b=>b.onclick=()=>preview(b.dataset.backupPreview));}catch(e){status(e.message,true)}};
